// Tensor-core FlashAttention forward (sm_86): wmma m16n16k16 bf16, 4 warps,
// BLOCK_M=64 query rows, BLOCK_N=64 keys/tile, online softmax in exp2 domain,
// GQA support. BF16 in/out, FP32 accumulation.
//
// Warp w owns query rows [16w, 16w+16). Q lives in registers as 8 wmma A
// fragments (16x16x16, row-major, ldm 128). K/V tiles staged in shared.
// Per K/V tile: 4 QK mma -> S accs (16 rows x 64 cols); softmax per row
// (warp-local: lane holds rows {gid, gid+8}, cols {2*tig, 2*tig+1}); then
// 32 PV mma accumulate O (8 d-half fragments). P fragments are assembled
// from softmaxed S via shfl_xor(2) (cols 2*tig+8 live in lane tig+2).

#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda_bf16.h>
#include <mma.h>
#include <math.h>

namespace {

constexpr int BLOCK_M = 64;
constexpr int BLOCK_N = 64;
constexpr int HEAD_DIM = 128;
constexpr int NUM_WARPS = 4;
constexpr int NUM_THREADS = NUM_WARPS * 32;
constexpr float LOG2E = 1.4426950408889634f;
constexpr float NEG_INF = -INFINITY;

using namespace nvcuda;

__device__ __forceinline__ uint32_t pack2bf16(float lo, float hi) {
    union { __nv_bfloat16 h[2]; uint32_t u; } v;
    v.h[0] = __float2bfloat16(lo);
    v.h[1] = __float2bfloat16(hi);
    return v.u;
}

__global__ void __launch_bounds__(NUM_THREADS, 2) attention_fwd_kernel(
    const __nv_bfloat16* __restrict__ q,
    const __nv_bfloat16* __restrict__ k,
    const __nv_bfloat16* __restrict__ v,
    __nv_bfloat16* __restrict__ out,
    int seq_len, float scale_log2, bool causal, int q_per_kv)
{
    __shared__ __nv_bfloat16 sK[BLOCK_N][HEAD_DIM];
    __shared__ __nv_bfloat16 sV[BLOCK_N][HEAD_DIM];

    const int m_tile = blockIdx.x;
    const int bh = blockIdx.y;
    const int warp = threadIdx.x / 32;
    const int lane = threadIdx.x % 32;
    const int gid = lane / 4, tig = lane % 4;   // wmma frag rows/cols

    const long long base = (long long)bh * seq_len * HEAD_DIM;
    const long long base_kv = (long long)(bh / q_per_kv) * seq_len * HEAD_DIM;
    const int grow0 = m_tile * BLOCK_M + warp * 16;

    // ---- Q A-fragments (8 halves of 16 dims), row-major ldm 128 ----
    wmma::fragment<wmma::matrix_a, 16, 16, 16, __nv_bfloat16, wmma::row_major> qf[8];
#pragma unroll
    for (int j = 0; j < 8; ++j)
        wmma::load_matrix_sync(qf[j], q + base + (long long)grow0 * HEAD_DIM + j * 16, HEAD_DIM);

    // ---- O accumulators ----
    wmma::fragment<wmma::accumulator, 16, 16, 16, float> acc_o[8];
#pragma unroll
    for (int j = 0; j < 8; ++j) wmma::fill_fragment(acc_o[j], 0.0f);

    // ---- online softmax state (exp2 domain): rows gid and gid+8 ----
    float m2[2] = {NEG_INF, NEG_INF}, l[2] = {0.f, 0.f};

    const int row_hi = min(m_tile * BLOCK_M + BLOCK_M - 1, seq_len - 1);
    int n_tiles = (seq_len + BLOCK_N - 1) / BLOCK_N;
    if (causal) n_tiles = min(n_tiles, row_hi / BLOCK_N + 1);
    if (grow0 >= seq_len) n_tiles = 0;

    for (int nt = 0; nt < n_tiles; ++nt) {
        // ---- load K/V tile (zero-pad rows >= seq_len) ----
        {
            const int nchunk = BLOCK_N * HEAD_DIM / 8;  // 16B units
            for (int i = threadIdx.x; i < nchunk; i += NUM_THREADS) {
                const int r = i / 16, u = i % 16;
                const int grow_kv = nt * BLOCK_N + r;
                if (grow_kv < seq_len) {
                    *reinterpret_cast<uint4*>(&sK[r][u * 8]) =
                        *reinterpret_cast<const uint4*>(k + base_kv + (long long)grow_kv * HEAD_DIM + u * 8);
                    *reinterpret_cast<uint4*>(&sV[r][u * 8]) =
                        *reinterpret_cast<const uint4*>(v + base_kv + (long long)grow_kv * HEAD_DIM + u * 8);
                } else {
                    *reinterpret_cast<uint4*>(&sK[r][u * 8]) = make_uint4(0, 0, 0, 0);
                    *reinterpret_cast<uint4*>(&sV[r][u * 8]) = make_uint4(0, 0, 0, 0);
                }
            }
        }
        __syncthreads();

        // ---- QK: 4 S accs (16 rows x 64 cols of this tile) ----
        wmma::fragment<wmma::accumulator, 16, 16, 16, float> s_acc[4];
        wmma::fragment<wmma::matrix_b, 16, 16, 16, __nv_bfloat16, wmma::col_major> kf[4];
#pragma unroll
        for (int g = 0; g < 4; ++g) {
            wmma::load_matrix_sync(kf[g], &sK[g * 16][0], HEAD_DIM);  // K^T
            wmma::fill_fragment(s_acc[g], 0.0f);
#pragma unroll
            for (int j = 0; j < 8; ++j)
                wmma::mma_sync(s_acc[g], qf[j], kf[g], s_acc[g]);
        }

        // ---- per-group softmax + PV ----
        const float col_base = (float)(nt * BLOCK_N);
        for (int g = 0; g < 4; ++g) {
            const int grow_kv0 = nt * BLOCK_N + g * 16;
            // element-wise p = exp2(s*scale_log2 - m2), masking cols >= S / causal
            float p[4];
            bool any_masked = false;
#pragma unroll
            for (int i = 0; i < 2; ++i) {
                const int col = 2 * tig + i;
                const int gcol = grow_kv0 + col;
                const bool mask = (gcol >= seq_len) || (causal && gcol > grow0 + gid);
                p[i] = mask ? 0.f : __exp2f(s_acc[g].x[i] * scale_log2 - m2[0]);
                p[i + 2] = mask ? 0.f : __exp2f(s_acc[g].x[i + 2] * scale_log2 - m2[1]);
                any_masked = any_masked || mask;
            }
            // rescale O by old/new max (skip when m unchanged)
            // (kept simple: always rescale; m2 updates only if needed)
            (void)any_masked; (void)col_base;
            // NOTE: online rescale folded below using m2[0]/m2[1] before update.

            // l update + O accumulation via 8 PV mma
            wmma::fragment<wmma::matrix_a, 16, 16, 16, __nv_bfloat16, wmma::row_major> pf;
            // pf regs: a0a1=(gid, 2tig,2tig+1), a2a3=(gid, 2tig+8,9), a4a5=(gid+8,...), a6a7=(gid+8, 2tig+8,9)
            pf.x[0] = pack2bf16(p[0], p[1]);
            pf.x[1] = pack2bf16(__shfl_xor_sync(0xffffffffu, p[0], 2),
                                __shfl_xor_sync(0xffffffffu, p[1], 2));
            pf.x[2] = pack2bf16(p[2], p[3]);
            pf.x[3] = pack2bf16(__shfl_xor_sync(0xffffffffu, p[2], 2),
                                __shfl_xor_sync(0xffffffffu, p[3], 2));
            l[0] += p[0] + p[1] + __shfl_xor_sync(0xffffffffu, p[0], 2) + __shfl_xor_sync(0xffffffffu, p[1], 2);
            l[1] += p[2] + p[3] + __shfl_xor_sync(0xffffffffu, p[2], 2) + __shfl_xor_sync(0xffffffffu, p[3], 2);
#pragma unroll
            for (int j = 0; j < 8; ++j) {
                wmma::fragment<wmma::matrix_b, 16, 16, 16, __nv_bfloat16, wmma::col_major> vf;
                wmma::load_matrix_sync(vf, &sV[g * 16][j * 16], HEAD_DIM);
                wmma::mma_sync(acc_o[j], pf, vf, acc_o[j]);
            }
        }

        // ---- online max correction for O and l (per row) ----
        // Group max of this tile per row: recompute from S (cheap, avoids
        // storing per-group max): m_tile_new = max over 64 cols.
        float tmax[2] = {NEG_INF, NEG_INF};
#pragma unroll
        for (int g = 0; g < 4; ++g) {
            float m0 = fmaxf(s_acc[g].x[0], s_acc[g].x[1]);
            float m1 = fmaxf(s_acc[g].x[2], s_acc[g].x[3]);
            m0 = fmaxf(m0, __shfl_xor_sync(0xffffffffu, m0, 1));
            m0 = fmaxf(m0, __shfl_xor_sync(0xffffffffu, m0, 2));
            m1 = fmaxf(m1, __shfl_xor_sync(0xffffffffu, m1, 1));
            m1 = fmaxf(m1, __shfl_xor_sync(0xffffffffu, m1, 2));
            tmax[0] = fmaxf(tmax[0], m0 * scale_log2);
            tmax[1] = fmaxf(tmax[1], m1 * scale_log2);
        }
        const float corr[2] = {__exp2f(m2[0] - tmax[0]), __exp2f(m2[1] - tmax[1])};
        l[0] = l[0] * corr[0] + 0.f;  // corrected below with tile sums
        l[1] = l[1] * corr[1] + 0.f;
        // l += tile softmax sums; O *= corr
        float lsum[2] = {0.f, 0.f};
#pragma unroll
        for (int g = 0; g < 4; ++g) {
            float a0 = __exp2f(s_acc[g].x[0] * scale_log2 - tmax[0]);
            float a1 = __exp2f(s_acc[g].x[1] * scale_log2 - tmax[0]);
            float a2 = __exp2f(s_acc[g].x[2] * scale_log2 - tmax[1]);
            float a3 = __exp2f(s_acc[g].x[3] * scale_log2 - tmax[1]);
            // mask cols >= S / causal
            const int gcol0 = nt * BLOCK_N + g * 16 + 2 * tig;
            if (gcol0 >= seq_len || (causal && gcol0 > grow0 + gid)) a0 = 0.f;
            if (gcol0 + 1 >= seq_len || (causal && gcol0 + 1 > grow0 + gid)) a1 = 0.f;
            if (gcol0 >= seq_len || (causal && gcol0 > grow0 + gid + 8)) a2 = 0.f;
            if (gcol0 + 1 >= seq_len || (causal && gcol0 + 1 > grow0 + gid + 8)) a3 = 0.f;
            a0 += __shfl_xor_sync(0xffffffffu, a0, 1);
            a0 += __shfl_xor_sync(0xffffffffu, a0, 2);
            a1 += __shfl_xor_sync(0xffffffffu, a1, 1);
            a1 += __shfl_xor_sync(0xffffffffu, a1, 2);
            a2 += __shfl_xor_sync(0xffffffffu, a2, 1);
            a2 += __shfl_xor_sync(0xffffffffu, a2, 2);
            a3 += __shfl_xor_sync(0xffffffffu, a3, 1);
            a3 += __shfl_xor_sync(0xffffffffu, a3, 2);
            lsum[0] += a0 * 0.25f + a1 * 0.25f;
            lsum[1] += a2 * 0.25f + a3 * 0.25f;
        }
        l[0] += lsum[0]; l[1] += lsum[1];
#pragma unroll
        for (int j = 0; j < 8; ++j) {
#pragma unroll
            for (int i = 0; i < 4; ++i) acc_o[j].x[i] *= corr[i / 2];
        }
        m2[0] = tmax[0]; m2[1] = tmax[1];
        __syncthreads();
    }

    // ---- epilogue: O / l -> bf16 ----
    if (grow0 + gid >= seq_len) return;
#pragma unroll
    for (int j = 0; j < 8; ++j) {
        const int grow = grow0 + gid;
        const int col = j * 16 + 2 * tig;
        if (grow < seq_len) {
            uint32_t lo = pack2bf16(acc_o[j].x[0] / l[0], acc_o[j].x[1] / l[0]);
            *reinterpret_cast<uint32_t*>(out + base + (long long)grow * HEAD_DIM + col) = lo;
        }
        const int grow2 = grow0 + gid + 8;
        if (grow2 < seq_len) {
            uint32_t hi = pack2bf16(acc_o[j].x[2] / l[1], acc_o[j].x[3] / l[1]);
            *reinterpret_cast<uint32_t*>(out + base + (long long)grow2 * HEAD_DIM + col) = hi;
        }
    }
}

}  // namespace

torch::Tensor attention_forward(torch::Tensor q, torch::Tensor k,
                                torch::Tensor v, bool causal)
{
    TORCH_CHECK(q.is_cuda() && k.is_cuda() && v.is_cuda(), "q/k/v must be CUDA tensors");
    TORCH_CHECK(q.scalar_type() == torch::kBFloat16 &&
                k.scalar_type() == torch::kBFloat16 &&
                v.scalar_type() == torch::kBFloat16, "q/k/v must be bfloat16");
    TORCH_CHECK(q.dim() == 4, "expected [B, H, S, D]");
    TORCH_CHECK(q.size(3) == HEAD_DIM, "head_dim must be ", HEAD_DIM);
    TORCH_CHECK(q.is_contiguous() && k.is_contiguous() && v.is_contiguous(),
                "q/k/v must be contiguous");
    TORCH_CHECK(k.size(1) <= q.size(1) && q.size(1) % k.size(1) == 0,
                "kv_heads must divide heads");
    TORCH_CHECK(k.size(1) == v.size(1) && q.size(0) == k.size(0) &&
                q.size(2) == k.size(2), "shape mismatch");

    const at::cuda::CUDAGuard guard(q.device());
    const int B = q.size(0), H = q.size(1), S = q.size(2);
    const int kv_heads = k.size(1);
    TORCH_CHECK((long long)B * H <= 65535, "B*H exceeds grid.y limit");

    auto out = torch::empty_like(q);
    const float scale = 1.0f / sqrtf((float)HEAD_DIM);
    const float scale_log2 = scale * LOG2E;
    dim3 grid((S + BLOCK_M - 1) / BLOCK_M, B * H);

    attention_fwd_kernel<<<grid, NUM_THREADS, 0,
                           at::cuda::getCurrentCUDAStream()>>>(
        reinterpret_cast<const __nv_bfloat16*>(q.data_ptr()),
        reinterpret_cast<const __nv_bfloat16*>(k.data_ptr()),
        reinterpret_cast<const __nv_bfloat16*>(v.data_ptr()),
        reinterpret_cast<__nv_bfloat16*>(out.data_ptr()),
        S, scale_log2, causal, H / kv_heads);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
